  "code": "// ===== DOOR ALARM SHIELD (ULTRASONIC) =====\nconst int TRIG_PIN   = 10;\nconst int ECHO_PIN   = 11;\nconst int RESET_PIN  = 3;\nconst int BUZZER_PIN = 9;\nconst int LED_PINS[] = {4, 5, 6, 7};\nconst int NUM_LEDS   = 4;\nconst int TRIGGER_CM = 30;\n\nbool alarmOn = false;\nunsigned long lastStep = 0;\nint step = 0;\n\nvoid setup() {\n  pinMode(TRIG_PIN, OUTPUT);\n  pinMode(ECHO_PIN, INPUT);\n  pinMode(RESET_PIN, INPUT_PULLUP);\n  pinMode(BUZZER_PIN, OUTPUT);\n  for (int i = 0; i < NUM_LEDS; i++) pinMode(LED_PINS[i], OUTPUT);\n  Serial.begin(9600);\n}\n\nlong readDistanceCm() {\n  digitalWrite(TRIG_PIN, LOW);  delayMicroseconds(2);\n  digitalWrite(TRIG_PIN, HIGH); delayMicroseconds(10);\n  digitalWrite(TRIG_PIN, LOW);\n  long duration = pulseIn(ECHO_PIN, HIGH, 30000);\n  if (duration == 0) return 999;\n  return duration * 0.034 / 2;\n}\n\nvoid loop() {\n  if (!alarmOn) {\n    long cm = readDistanceCm();\n    Serial.println(cm);\n    if (cm > 0 && cm < TRIGGER_CM) alarmOn = true;\n    delay(60);\n  }\n  if (digitalRead(RESET_PIN) == LOW) {\n    alarmOn = false;\n    noTone(BUZZER_PIN);\n    allLeds(LOW);\n    delay(1000);\n  }\n  if (alarmOn && millis() - lastStep >= 150) {\n    lastStep = millis();\n    step = (step + 1) % 4;\n    if (step % 2 == 0) tone(BUZZER_PIN, 1800);\n    else               tone(BUZZER_PIN, 1000);\n    bool redsOn = (step < 2);\n    digitalWrite(LED_PINS[0], redsOn);\n    digitalWrite(LED_PINS[1], redsOn);\n    digitalWrite(LED_PINS[2], !redsOn);\n    digitalWrite(LED_PINS[3], !redsOn);\n  }\n}\n\nvoid allLeds(int state) {\n  for (int i = 0; i < NUM_LEDS; i++) digitalWrite(LED_PINS[i], state);\n}\n",
